const API=['127.0.0.1','localhost'].includes(location.hostname)?'':'https://formula-auto-nv-mini.olegwest1112.chatgpt.site';
const $=s=>document.querySelector(s),tg=window.Telegram?.WebApp,money=n=>Number(n).toLocaleString('uk-UA'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusName={stock:'У наявності',road:'У дорозі',reserved:'Заброньовано',sold:'Продано'},read=key=>{try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v.filter(Number.isInteger):[];}catch{return [];}};
let cars=[],settings={},filter='all',view='catalog',selected=null,photo=0,requestId=null,sending=false,favorites=read('formula-favorites'),comparison=read('formula-compare').slice(0,3);
function persist(){try{localStorage.setItem('formula-favorites',JSON.stringify(favorites));localStorage.setItem('formula-compare',JSON.stringify(comparison));}catch{}}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3200);}
function img(src){return src?.startsWith('/media/')?'https://formula-auto-nv-mini.olegwest1112.chatgpt.site'+src:src;}
const mileageKm=c=>c.mileageValue*(c.mileageUnit==='mi'?1.609344:1);
function render(){const query=$('#search').value.trim().toLowerCase();let list=cars.filter(c=>(filter==='all'?c.status!=='sold':c.status===filter)&&(view!=='favorites'||favorites.includes(c.id))&&(c.name+' '+c.trim+' '+c.brand).toLowerCase().includes(query)&&(!$('#brand-filter').value||c.brand===$('#brand-filter').value)&&(!$('#fuel-filter').value||c.fuel===$('#fuel-filter').value)&&(!$('#price-min').value||c.price>=+$('#price-min').value)&&(!$('#price-max').value||c.price<=+$('#price-max').value)&&(!$('#year-min').value||c.year>=+$('#year-min').value));const sort=$('#sort').value;if(sort==='price-asc')list.sort((a,b)=>a.price-b.price);if(sort==='price-desc')list.sort((a,b)=>b.price-a.price);if(sort==='year')list.sort((a,b)=>b.year-a.year);if(sort==='mileage')list.sort((a,b)=>mileageKm(a)-mileageKm(b));$('#count').textContent=String(list.length).padStart(2,'0');$('#fav-count').textContent=favorites.filter(id=>cars.some(c=>c.id===id)).length;$('#compare-count').textContent=comparison.length;$('#grid').innerHTML=list.length?list.map(c=>`<article class="card"><div class="photo"><button class="photo-open" data-detail="${c.id}" aria-label="Переглянути ${esc(c.name)}"><img src="${esc(img(c.images[0]))}" alt="${esc(c.name)} — ${c.year}" loading="lazy"></button><span class="badge ${c.status}">${statusName[c.status]}</span><button class="heart ${favorites.includes(c.id)?'saved':''}" data-fav="${c.id}" aria-label="Обране: ${esc(c.name)}" aria-pressed="${favorites.includes(c.id)}"><svg class="ui-icon icon-heart" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-heart"></use></svg></button></div><div class="card-body"><div class="card-top"><h3>${esc(c.name)}</h3><span class="year">${c.year}</span></div><p class="trim">${esc(c.trim||c.fuel)}</p><div class="specs"><span>${esc(c.mileage)}</span><span>${esc(c.engine)}</span><span>${esc(c.gear)}</span></div><div class="card-bottom"><span class="price">${money(c.price)} <small>$</small></span><button class="detail-btn" data-detail="${c.id}">Детальніше <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></button></div>${c.priceNote?`<p class="price-note">${esc(c.priceNote)}</p>`:''}<button class="compare-check ${comparison.includes(c.id)?'selected':''}" data-compare="${c.id}" aria-pressed="${comparison.includes(c.id)}">${comparison.includes(c.id)?'<svg class="ui-icon icon-check" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-check"></use></svg> У порівнянні':'<svg class="ui-icon icon-plus" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-plus"></use></svg> Порівняти автомобіль'}</button></div></article>`).join(''):`<div class="empty"><h3>${view==='favorites'?'Твій особистий вибір':'Зараз немає відповідних авто'}</h3><p>${view==='favorites'?'Додавай автомобілі сердечком у картці.':'Зміни фільтри або залиш побажання — допоможемо з підбором.'}</p><button class="secondary" id="reset">Скинути фільтри</button><button class="primary" data-request="import">Замовити підбір</button></div>`;$('#reset')?.addEventListener('click',reset);}
function reset(){for(const id of ['search','brand-filter','fuel-filter','price-min','price-max','year-min'])$('#'+id).value='';filter='all';syncFilters();setView('catalog');}
function syncFilters(){document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter));});}
function setView(v){view=v;$('#catalog').hidden=v==='contacts';$('#contacts').hidden=v!=='contacts';$('#services').hidden=v!=='catalog';$('.intro').hidden=v!=='catalog';$('#view-title').firstChild.textContent=v==='favorites'?'Обране ':'Каталог ';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-current',b.dataset.view===v?'page':'false');});render();}
function contacts(){$('#contacts').innerHTML=`<p class="eyebrow">ЗНАЙОМСТВО ПОЧИНАЄТЬСЯ З РОЗМОВИ</p><h2>Завітай у Formula</h2><div class="contact-layout"><div class="contact-box"><h3>Нововолинськ</h3><p class="address">${esc(settings.address)}</p><p>${esc(settings.hours)}</p><a class="primary" href="tel:${esc(settings.phone.replace(/[^+\d]/g,''))}">${esc(settings.phone)} <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></a><a class="secondary" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(settings.address)}" target="_blank" rel="noopener">Прокласти маршрут <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></a><p><a href="${esc(settings.instagram)}" target="_blank" rel="noopener">Instagram Formula <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></a></p></div><div class="contact-note"><div><p class="eyebrow">ТВІЙ НАСТУПНИЙ АВТОМОБІЛЬ</p><h3>Почнемо<br>з розмови.</h3><p>Уточни наявність, домовся про перегляд або розкажи, яке авто шукаєш.</p></div><a class="secondary" href="https://t.me/${esc(settings.managerUsername)}" target="_blank" rel="noopener">Написати менеджеру <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></a><button class="secondary" data-request="consultation">Залишити заявку</button></div></div>`;$('#channel-link').href='https://t.me/'+settings.channelUsername;}
function gallery(){const c=selected;$('#main-photo').src=img(c.images[photo]);$('#main-photo').alt=c.name+' — фото '+(photo+1);$('#photo-position').textContent=`${photo+1} / ${c.images.length}`;document.querySelectorAll('[data-photo]').forEach(b=>b.classList.toggle('active',+b.dataset.photo===photo));}
function showDetail(id,updateHash=true){selected=cars.find(c=>c.id===id);if(!selected){toast('Ця картка зараз недоступна.');return;}const c=selected;photo=0;$('#detail-body').innerHTML=`<div class="gallery-main"><img id="main-photo" src="${esc(img(c.images[0]))}" alt="${esc(c.name)}"><button class="gallery-arrow prev" data-step="-1" aria-label="Попереднє фото"><svg class="ui-icon icon-chevron-left" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-chevron-left"></use></svg></button><button class="gallery-arrow next" data-step="1" aria-label="Наступне фото"><svg class="ui-icon icon-chevron-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-chevron-right"></use></svg></button></div><div class="thumbs">${c.images.map((src,i)=>`<button data-photo="${i}" aria-label="Фото ${i+1}"><img src="${esc(img(src))}" alt="" loading="lazy"></button>`).join('')}</div><div class="detail-content"><p class="gallery-hint">Фото <span id="photo-position"></span></p><p class="eyebrow">${statusName[c.status]}</p><h2 id="detail-title">${esc(c.name)}</h2><p class="trim">${esc(c.trim)} · ${c.year}</p><div class="price">${money(c.price)} <small>$</small></div><p class="hint">${esc(c.priceNote||'Ціна автомобіля')}. Умови та актуальність уточнюйте у менеджера.</p><dl class="facts">${[['Пробіг',c.mileage],['Двигун',c.engine],['Коробка',c.gear],['Привід',c.drive||'Уточнюється'],['Рік',c.year],['VIN',c.vin||'За запитом']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><button class="primary" data-enquire>${c.status==='sold'?'Підібрати схоже авто':c.status==='road'?'Дізнатися про доставку':'Записатися на перегляд'} <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></button><div class="detail-actions"><button class="secondary" id="share">Поділитися <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></button>${c.source?`<a class="secondary" href="${esc(c.source)}" target="_blank" rel="noopener">Оголошення <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></a>`:''}</div>${c.equipment.length?`<h3>Комплектація</h3><ul class="equipment">${c.equipment.map(v=>`<li><svg class="ui-icon icon-check" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-check"></use></svg><span>${esc(v)}</span></li>`).join('')}</ul>`:''}${c.description?`<details><summary>Повний опис</summary><p class="description">${esc(c.description)}</p></details>`:''}</div>`;gallery();if(!$('#detail').open)$('#detail').showModal();tg?.BackButton?.show();if(updateHash)history.replaceState(null,'','#car/'+id);$('#share').onclick=async()=>{const url=location.origin+location.pathname+'#car/'+c.id;try{if(navigator.share)await navigator.share({title:c.name+' — Formula',url});else{await navigator.clipboard.writeText(url);toast('Посилання скопійовано');}}catch(error){if(error.name!=='AbortError')toast('Скопіюйте посилання з адресного рядка.');}};}
function request(intent='consultation',car=null){if(sending)return;selected=car;requestId=crypto.randomUUID();$('#lead-form').reset();$('#lead-form').elements.intent.value=intent;$('#own-car-label').hidden=intent!=='tradein';$('#request-car').textContent=car?`${car.name} · ${car.year} · ${money(car.price)} $`:'Розкажи, що шукаєш. Ми допоможемо з наступним кроком.';$('#lead-status').textContent='';$('#lead-form button[type=submit]').disabled=false;$('#lead-form button[type=submit]').innerHTML='Надіслати заявку <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg>';$('#request-hint').textContent=settings.testMode?'Тестовий режим: заявка збережеться та надійде тестовому менеджеру.':'Заявка збережеться і надійде менеджеру. Він зв’яжеться за вказаним номером.';$('#detail').close();$('#request').showModal();tg?.BackButton?.show();}
function compare(){const list=comparison.map(id=>cars.find(c=>c.id===id)).filter(Boolean);$('#comparison').innerHTML=list.length?`<table><tbody><tr><th>Автомобіль</th>${list.map(c=>`<td><img src="${esc(img(c.images[0]))}" alt=""><strong>${esc(c.name)}</strong><button class="text-button" data-remove-compare="${c.id}">Прибрати <svg class="ui-icon icon-close" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-close"></use></svg></button></td>`).join('')}</tr>${[['Ціна',c=>money(c.price)+' $'],['Рік',c=>c.year],['Пробіг',c=>c.mileage],['Двигун',c=>c.engine],['Коробка',c=>c.gear],['Привід',c=>c.drive||'Уточнюється'],['Наявність',c=>statusName[c.status]]].map(([label,fn])=>`<tr><th>${label}</th>${list.map(c=>`<td>${esc(fn(c))}</td>`).join('')}</tr>`).join('')}<tr><th></th>${list.map(c=>`<td><button class="secondary" data-compare-detail="${c.id}">Детальніше <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></button></td>`).join('')}</tr></tbody></table>`:'<div class="empty">Додай до трьох автомобілів кнопкою «Порівняти» в каталозі.</div>';if(!$('#compare').open)$('#compare').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.detail!==undefined)showDetail(+b.dataset.detail);if(b.dataset.fav!==undefined){const id=+b.dataset.fav;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persist();render();}if(b.dataset.compare!==undefined){const id=+b.dataset.compare;if(comparison.includes(id))comparison=comparison.filter(x=>x!==id);else if(comparison.length<3)comparison.push(id);else return toast('Можна порівняти до трьох автомобілів.');persist();render();}if(b.dataset.filter){filter=b.dataset.filter;syncFilters();render();}if(b.dataset.view){setView(b.dataset.view);window.scrollTo({top:0,behavior:'smooth'});}if(b.dataset.photo!==undefined){photo=+b.dataset.photo;gallery();}if(b.dataset.step){photo=(photo+Number(b.dataset.step)+selected.images.length)%selected.images.length;gallery();}if(b.hasAttribute('data-enquire'))request(selected.status==='sold'?'import':'viewing',selected.status==='sold'?null:selected);if(b.dataset.request)request(b.dataset.request);if(b.dataset.removeCompare!==undefined){comparison=comparison.filter(id=>id!==+b.dataset.removeCompare);persist();render();compare();}if(b.dataset.compareDetail!==undefined){$('#compare').close();showDetail(+b.dataset.compareDetail);}});
for(const id of ['search','sort','brand-filter','fuel-filter','price-min','price-max','year-min'])$('#'+id).addEventListener('input',render);
$('#filter-toggle').onclick=()=>{$('#advanced').hidden=!$('#advanced').hidden;$('#filter-toggle').setAttribute('aria-expanded',String(!$('#advanced').hidden));};$('#clear-filters').onclick=reset;$('#compare-open').onclick=compare;$('#privacy-open').onclick=()=>$('#privacy').showModal();$('.brand').onclick=e=>{e.preventDefault();setView('catalog');};$('.location').onclick=e=>{e.preventDefault();setView('contacts');};$('#lead-form').elements.intent.onchange=e=>$('#own-car-label').hidden=e.target.value!=='tradein';
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>{if(d.id==='request'&&sending)return;d.close();};d.addEventListener('cancel',e=>{if(d.id==='request'&&sending)e.preventDefault();});d.addEventListener('close',()=>{if(d.id==='detail'&&location.hash.startsWith('#car/'))history.replaceState(null,'',location.pathname+location.search);if(!document.querySelector('dialog[open]'))tg?.BackButton?.hide();});});
$('#lead-form').onsubmit=async e=>{e.preventDefault();if(sending)return;const form=e.target,data=Object.fromEntries(new FormData(form));data.consent=form.elements.consent.checked;data.carId=selected?.id??null;sending=true;const button=form.querySelector('button[type=submit]');button.disabled=true;$('#lead-status').textContent='Надсилаємо заявку…';try{const response=await fetch(API+'/api/leads',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':requestId},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Помилка надсилання.');$('#lead-status').textContent=`Заявку збережено. Номер: ${result.id.slice(0,8)}.\n${result.notified?'Менеджеру надіслано повідомлення.':'Менеджер побачить звернення в панелі заявок.'}`;form.reset();button.innerHTML='Заявку прийнято <svg class="ui-icon icon-check" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-check"></use></svg>';}catch(error){$('#lead-status').textContent=error.message==='Failed to fetch'?'Немає зв’язку із сервером. Дані залишилися у формі — повторіть спробу.':error.message;button.disabled=false;}finally{sending=false;}};
async function load(){try{const r=await fetch(API+'/api/catalog',{cache:'no-store'});if(!r.ok)throw new Error();const data=await r.json();cars=data.cars;settings=data.settings;comparison=comparison.filter(id=>cars.some(c=>c.id===id));persist();for(const [id,key,label] of [['brand-filter','brand','Усі марки'],['fuel-filter','fuel','Будь-яке']])$('#'+id).innerHTML=`<option value="">${label}</option>`+[...new Set(cars.map(c=>c[key]).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');contacts();render();if(/^#car\/\d+$/.test(location.hash))showDetail(Number(location.hash.split('/')[1]),false);}catch{$('#grid').innerHTML='<div class="empty"><h3>Каталог тимчасово недоступний</h3><p>Перевірте підключення та повторіть спробу.</p><button class="secondary" id="retry-load">Спробувати ще раз</button><a class="primary" href="https://t.me/beloeeet3535" target="_blank" rel="noopener">Написати менеджеру <svg class="ui-icon icon-arrow-right" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-arrow-right"></use></svg></a></div>';$('#retry-load').onclick=load;}}
if(tg?.initData){tg.ready();tg.expand();if(tg.isVersionAtLeast?.('6.1')){tg.setHeaderColor('#202020');tg.setBackgroundColor('#f4f5f6');tg.BackButton.onClick(()=>{if(!sending)document.querySelector('dialog[open]')?.close();});}}
window.addEventListener('hashchange',()=>{if(/^#car\/\d+$/.test(location.hash))showDetail(Number(location.hash.split('/')[1]),false);});load();
